{
  "items": [
    {
      "term": {
        "text": "array",
        "refs": ["Q0013", "Q0014", "Q0015", "Q0016"],
        "claims": [
          {
            "text": "In Java, arrays have a fixed size and a fixed length.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0013", "Q0014", "Q0015", "Q0016"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "Once an array is created, its size cannot be changed; you cannot add or remove items.",
        "refs": ["Q0013", "Q0014", "Q0015", "Q0016"],
        "claims": [
          {
            "text": "Arrays have a fixed length and cannot be resized after creation.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0013", "Q0014", "Q0015", "Q0016"],
            "related_refs": []
          }
        ]
      },
      "context": null
    },
    {
      "term": {
        "text": "multi‑dimensional array",
        "refs": ["Q0027", "Q0028", "Q0031", "Q0032", "Q0034", "Q0035", "Q0036"],
        "claims": [
          {
            "text": "A multi‑dimensional array is an array whose elements are themselves arrays, allowing storage of matrices or higher‑dimensional data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0027", "Q0028", "Q0031", "Q0032", "Q0034", "Q0035", "Q0036"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "To create a two‑dimensional array you add another pair of square brackets and specify lengths for rows and columns.",
        "refs": ["Q0032", "Q0034", "Q0035", "Q0036"],
        "claims": [
          {
            "text": "A two‑dimensional array is declared with two sets of brackets and initialized with row and column sizes.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0032", "Q0034", "Q0035", "Q0036"],
            "related_refs": []
          }
        ]
      },
      "context": null
    },
    {
      "term": {
        "text": "array length",
        "refs": ["Q0007", "Q0008", "Q0010", "Q0011", "Q0012"],
        "claims": [
          {
            "text": "The length field of an array gives the number of elements it contains.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0007", "Q0008", "Q0010", "Q0011", "Q0012"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "You can read the number of items in an array using its length field.",
        "refs": ["Q0008", "Q0010", "Q0011", "Q0012"],
        "claims": [
          {
            "text": "The length property returns the number of elements in the array.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0008", "Q0010", "Q0011", "Q0012"],
            "related_refs": []
          }
        ]
      },
      "context": null
    },
    {
      "term": {
        "text": "array initialization",
        "refs": ["Q0003", "Q0004", "Q0005", "Q0006"],
        "claims": [
          {
            "text": "Arrays can be initialized using curly braces with a comma‑separated list of values.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0003", "Q0004", "Q0005", "Q0006"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "A newer syntax for array creation uses curly braces to list all items at declaration time.",
        "refs": ["Q0004", "Q0005", "Q0006"],
        "claims": [
          {
            "text": "You can initialize an array by specifying its elements inside curly braces when declaring it.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0004", "Q0005", "Q0006"],
            "related_refs": []
          }
        ]
      },
      "context": null
    }
  ],
  "abstentions": [],
  "excluded": []
}
